arguments.command:
cd /tmp/sv-abfdd49d721a4d3d9ad0a30db6e529b6/symbols && \
# Try using nm to get dynamic symbols and then manually resolve
nm -D --defined-only libmonosgen-2.0.so 2>/dev/null | sort | head -5 && echo "---" && \
nm -D --defined-only libmonosgen-2.0.so 2>/dev/null | wc -l && echo "total dynamic symbols" && \
# Find the nearest symbol for each address
for addr in 0x222098 0x222234 0x19bac0 0x19bc14; do
  echo "=== $addr ==="
  nm -D --defined-only libmonosgen-2.0.so 2>/dev/null | sort | awk -v target="$addr" '
    BEGIN { gsub(/^0x/, "", target); best_name="??"; best_addr=0; target_dec=strtonum("0x" target) }
    { 
      addr_dec = strtonum("0x" $1)
      if (addr_dec <= target_dec && addr_dec > best_addr) {
        best_addr = addr_dec
        best_name = $3
        best_hex = $1
      }
    }
    END { printf "  %s + 0x%x  (symbol at 0x%s)\n", best_name, target_dec - best_addr, best_hex }
  '
done

